const editor = $('Prepare Editor Input').first().json;

const text = String(input.text ?? '');

if (!text.trim()) {
  throw new Error('PHI_GATE_EMPTY_INPUT');
}

// Read Presidio detections.
let ents = $('Presidio analyze 2')
  .all()
  .map(item => item.json)
  .flatMap(json => Array.isArray(json) ? json : [json])
  .filter(e =>
    e &&
    Number.isInteger(e.start) &&
    Number.isInteger(e.end)
  );

const KEEP = new Set([
  'PERSON',
  'PHONE_NUMBER',
  'EMAIL_ADDRESS',
  'LOCATION',
  'US_SSN',
  'US_PASSPORT',
  'US_DRIVER_LICENSE',
  'IP_ADDRESS',
  'DATE_TIME'
]);

// Preserve recognized radiology descriptors.
const clinicalDescriptors = new Set([
  'lobulated',
  'irregular',
  'smooth',
  'ill-defined',
  'hypoechoic',
  'hyperechoic',
  'isoechoic',
  'anechoic',
  'taller-than-wide',
  'wider-than-tall',
  'solid',
  'spongiform',
  'punctate echogenic foci'
]);

function isClinicalDescriptor(entity) {
  if (entity.entity_type !== 'PERSON') return false;

  const value = text
    .slice(entity.start, entity.end)
    .trim()
    .toLowerCase();

  if (!clinicalDescriptors.has(value)) return false;

  const before = text.slice(
    Math.max(0, entity.start - 60),
    entity.start
  );

  return /(?:margins?|echogenicity|composition|shape|echogenic foci)\s*:\s*$/i
    .test(before);
}

ents = ents.filter(e =>
  KEEP.has(e.entity_type) &&
  Number(e.score) >= 0.5 &&
  !isClinicalDescriptor(e)
);

// Detect structured identifiers missed by Presidio.
function add(regex, type, group = 0) {
  for (const match of text.matchAll(regex)) {
    const value = match[group];

    if (!value) continue;

    const offset = match[0].lastIndexOf(value);
    const start = match.index + offset;

    ents.push({
      entity_type: type,
      start,
      end: start + value.length,
      score: 1
    });
  }
}

add(/\b[23]\d{13}\b/g, 'NATIONAL_ID');

add(
  /\bMRN\s*[:#]?\s*(\d{5,})\b/gi,
  'MRN',
  1
);

add(
  /\b(?:DOB|date\s+of\s+birth|birth\s+date)\s*:\s*(\d{1,2}[/-]\d{1,2}[/-]\d{4}|\d{4}-\d{2}-\d{2})/gi,
  'DOB',
  1
);

add(
  /\b(?:patient\s+name|patient's\s+name)\s*:\s*([^\n\r,;]+)/gi,
  'PERSON',
  1
);

// Resolve overlaps.
ents = ents.filter(e =>
  e.start >= 0 &&
  e.end <= text.length &&
  e.end > e.start
);

ents.sort((a, b) =>
  Number(b.score) - Number(a.score) ||
  (b.end - b.start) - (a.end - a.start)
);

const kept = [];

for (const entity of ents) {
  const overlaps = kept.some(existing =>
    entity.start < existing.end &&
    entity.end > existing.start
  );

  if (!overlaps) {
    kept.push(entity);
  }
}

kept.sort((a, b) => a.start - b.start);

// Replace detected identifiers.
let out = '';
let cursor = 0;

const mapping = {};
const counters = {};
const seen = {};

for (const entity of kept) {
  const value = text.slice(entity.start, entity.end);
  const type = entity.entity_type;

  const key = type + '|' + value.toLowerCase();

  if (!seen[key]) {
    counters[type] = (counters[type] || 0) + 1;

    const placeholder = `[${type}_${counters[type]}]`;

    seen[key] = placeholder;
    mapping[placeholder] = value;
  }

  out += text.slice(cursor, entity.start);
  out += seen[key];

  cursor = entity.end;
}

out += text.slice(cursor);

// Separate the report and feedback using the
// original known section boundaries.
const reportHeader = 'CURRENT REPORT:\n';
const feedbackHeader = '\nDOCTOR REQUESTED EDITS:\n';

if (!out.startsWith(reportHeader)) {
  throw new Error('INVALID_REPORT_SECTION');
}

const separatorIndex = out.lastIndexOf(feedbackHeader);

if (separatorIndex < reportHeader.length) {
  throw new Error('INVALID_FEEDBACK_SECTION');
}

const safeReport = out.slice(
  reportHeader.length,
  separatorIndex
).trim();

const safeFeedback = out.slice(
  separatorIndex + feedbackHeader.length
).trim();

if (!safeReport || !safeFeedback) {
  throw new Error('EMPTY_SANITIZED_REPORT_OR_FEEDBACK');
}

// Return sanitized data.
return [{
  json: {
    userPrompt: out,

    current_report: safeReport,
    original_report: safeReport,
    doctor_feedback: safeFeedback,

    mapping,

    chat_id: editor.chat_id ?? null,
    version: editor.version ?? 1,
    responded_at: editor.responded_at ?? null
  }
}];

