/**
 * RADRAFT — RE-IDENTIFICATION 2
 * Restores authorized PHI placeholders following
 * the targeted AI report editing stage.
 *
 * Mapping source: De-identify 2
 * AI output: AI Report Editor - Targeted Edits Only
 */

const mapping = $('De-identify 2').first().json.mapping ?? {};

if (
  !mapping ||
  typeof mapping !== 'object' ||
  Array.isArray(mapping)
) {
  throw new Error('Invalid re-identification mapping.');
}

const source = $('Prepare Editor Input').first().json;

const results = [];

for (const item of $input.all()) {
  const raw = item.json.output;

  if (typeof raw !== 'string' || !raw.trim()) {
    throw new Error('AI Editor report output is missing.');
  }

  let report = raw;
  let restored = 0;

  report = report.replace(
    /\[[A-Z][A-Z0-9_]*_\d+\]/g,
    placeholder => {
      if (Object.prototype.hasOwnProperty.call(mapping, placeholder)) {
        restored++;
        return String(mapping[placeholder]);
      }

      return placeholder;
    }
  );

  results.push({
    json: {
      ...item.json,
      output: report,
      current_report: report,
      chat_id: source.chat_id ?? null,
      version: Number(source.version ?? 1) + 1,
      reidentification_status: restored > 0
        ? 'COMPLETED'
        : 'NO_MATCHING_PLACEHOLDERS',
      restored_identifiers: restored
    }
  });
}

return results;

