/**
 * RADRAFT — RE-IDENTIFICATION 3
 * Restores authorized identifiers after repeated
 * doctor-requested report adjustments.
 *
 * Input:
 *   11B. AI Report Editor - Repeat Adjustment
 *
 * Mapping:
 *   De-identify 3
 *
 * Mode: Run Once for All Items
 */

const source = $('Prepare Next Editor Input').first().json;

const mapping = $('De-identify 3').first().json.mapping ?? {};

if (
  typeof mapping !== 'object' ||
  mapping === null ||
  Array.isArray(mapping)
) {
  throw new Error(
    'REIDENTIFICATION_3: Invalid PHI mapping.'
  );
}

const results = [];

for (const item of $input.all()) {

  const rawReport = item.json.output;

  if (
    typeof rawReport !== 'string' ||
    !rawReport.trim()
  ) {
    throw new Error(
      'REIDENTIFICATION_3: AI Editor output is missing.'
    );
  }

  let restoredCount = 0;

  const report = rawReport.replace(
    /\[[A-Z][A-Z0-9_]*_\d+\]/g,
    placeholder => {

      if (
        Object.prototype.hasOwnProperty.call(
          mapping,
          placeholder
        )
      ) {
        const original = mapping[placeholder];

        if (typeof original !== 'string') {
          throw new Error(
            'REIDENTIFICATION_3: Invalid mapping value.'
          );
        }

        restoredCount++;

        return original;
      }

      return placeholder;
    }
  );

  const currentVersion = Number(source.version ?? 1);

  if (
    !Number.isInteger(currentVersion) ||
    currentVersion < 1
  ) {
    throw new Error(
      'REIDENTIFICATION_3: Invalid report version.'
    );
  }

  results.push({
    json: {
      ...item.json,

      output: report,
      current_report: report,

      original_report:
        source.original_report ??
        source.current_report ??
        null,

      chat_id:
        source.chat_id !== undefined &&
        source.chat_id !== null
          ? String(source.chat_id)
          : null,

      doctor_feedback:
        source.doctor_feedback ?? null,

      version: currentVersion + 1,

      responded_at:
        source.responded_at ?? null,

      doctor_name:
        source.doctor_name ?? null,

      session_id:
        source.session_id ?? null,

      report_id:
        source.report_id ?? null,

      reidentification_status:
        restoredCount > 0
          ? 'COMPLETED'
          : 'NO_MATCHING_PLACEHOLDERS',

      restored_identifiers: restoredCount
    }
  });
}

return results;

const old = $('Prepare Next Editor Input').last().json;
const output = String($json.output ?? $json.text ?? '').trim();

if (!output) {
  throw new Error('AI editor returned an empty report');
}

return [{
  json: {
    case_id: old.case_id,
    chat_id: old.chat_id,
    current_report: output,
    doctor_feedback: old.doctor_feedback,
    version: (Number(old.version) || 1) + 1,
    status: 'PENDING_DOCTOR_REVIEW',
    updated_at: new Date().toISOString()
  }
}];
